# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "0.7.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v0.7.0/dedup-0.7.0-macos-arm64.tar.gz"
      sha256 "6c18ba6330f5c28a782696e9721142b7f4222eb79247eb168e2f05e21d3d740d"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v0.7.0/dedup-0.7.0-macos-x86_64.tar.gz"
      sha256 "76933cd29818aabc8b6c37fee0cace1e18bb18e5505b9d669f643a4a732e2d36"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v0.7.0/dedup-0.7.0-linux-x86_64.tar.gz"
    sha256 "e7dfb2660e820ae8577e3c63e3c5207267e06a927bd1aa4237b1e2f664245091"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
